"use client";

import { useState } from "react";
import { AccessRequest, type AccessRequester } from "@/components/ui/access-request";

export function RequestReview({ initialRequests }: { initialRequests: AccessRequester[] }) {
  const [requests, setRequests] = useState(initialRequests);

  return (
    <AccessRequest
      requests={requests}
      onDecision={async (person, decision, signal) => {
        const response = await fetch(`/api/access-requests/${encodeURIComponent(person.id)}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ decision }),
          signal,
        });
        if (!response.ok) throw new Error("Decision was not saved");
      }}
      onResolved={(person) => setRequests((current) => current.filter((item) => item.id !== person.id))}
      stiffness={420}
      damping={28}
    />
  );
}

