gsap.registerPlugin(useGSAP);

export interface AccessRequestProps {
  requests: readonly AccessRequester[];
  onDecision: (
    person: AccessRequester,
    decision: AccessDecision,
    signal: AbortSignal,
  ) => void | Promise<void>;
