              >
                {busy && decision === value ? (
                  <LoaderCircle
                    data-request-spinner
                    size={12}
                    aria-hidden="true"
                  />
                ) : value === "approved" ? (
                  "Approve"
                ) : (
                  "Decline"
                )}
              </button>
            ))}
          </div>
        )}
        {error && (
          <p
            role="alert"
            className="col-start-2 col-end-4 pt-1.5 text-[11px] leading-4 text-red-600 dark:text-red-400"
          >
            {error}
          </p>
        )}
      </div>
    </li>
  );
}

